Object.assign(SNIP,{});PRESET_NOTES["l34"]={"Ví dụ: Băm tiền tố và so sánh đoạn con": "H[i] là băm của tiền tố dài i. Đoạn [0, 3) và [3, 6) cùng là “abc” nên cùng số; [1, 4) = “bca” và [4, 7) = “bca” cũng vậy; “ab” và “bc” khác số. Mỗi lần so sánh chỉ là vài phép nhân, trừ, không phụ thuộc độ dài đoạn.", "Ví dụ: Rabin–Karp tìm mọi vị trí của mẫu": "Tính băm của mẫu trước (dùng chung mảng H nên phải lấy hp trước khi chuẩn bị cho s). Rồi trượt cửa sổ dài 4 trên s, mỗi vị trí so một con số. Mẫu “abra” xuất hiện ở vị trí 0 và 7.", "Ví dụ: Đếm đoạn con độ dài k khác nhau": "Các đoạn dài 3: aba, bab, aba, bab, abb, bba. Đưa băm của chúng vào tập hợp: còn 4 giá trị khác nhau. Không cần lưu các chuỗi con (tiết kiệm bộ nhớ và thời gian so sánh).", "Lỗi: hàm băm bằng tổng mã ký tự": "“listen” và “silent” gồm cùng các chữ cái nên tổng mã bằng nhau, hàm “băm” này nói chúng giống nhau. Băm đa thức nhân mỗi ký tự với một lũy thừa của B theo vị trí, nên đổi chỗ ký tự sẽ đổi giá trị băm."};EX_HINTS["l34"]=[["Tính hp = băm của p trước, vì chuanBi(s) sẽ ghi đè mảng H.", "Với mỗi i từ 0 tới |s| − |p|: so bam(i, i + |p|) với hp, O(1) mỗi lần.", "So từng ký tự (hay s.substr(i, m) == p) tốn O(|p|) mỗi vị trí: O(n · m) khi văn bản và mẫu gần giống nhau."], ["Mỗi đoạn s[i..i+k) được đại diện bằng một con số bam(i, i + k), tính O(1).", "Đưa các số vào unordered_set rồi lấy size().", "Đưa chính các chuỗi con (s.substr) vào tập hợp tốn O(k) mỗi đoạn để chép và băm: O(n · k)."], ["Đoạn s[a..b] (đánh số từ 1, tính cả hai đầu) chính là đoạn [a − 1, b) theo chỉ số từ 0.", "Mỗi câu hỏi chỉ so hai con số: O(1).", "So từng ký tự tốn O(độ dài) mỗi câu hỏi: tổng O(n · q)."]];
/* ===================== BÀI 34 · Băm chuỗi ===================== */
/* Bài 34 · Băm chuỗi
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR34=[{label:"Ví dụ: Băm tiền tố và so sánh đoạn con",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    string s = \"abcabcab\";\n    chuanBi(s);\n    cout << bam(0, 3) << \" \" << bam(3, 6) << \"\\n\";    // \"abc\" và \"abc\"\n    cout << (bam(0, 3) == bam(3, 6)) << \" \" << (bam(1, 4) == bam(4, 7)) << \" \" << (bam(0, 2) == bam(1, 3)) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"cells",of:"H",ptr:["i+1"],label:"H (băm tiền tố)"}],py:{code:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\ns = \"abcabcab\"\nH, Pw = chuanBi(s)\nprint(bam(H, Pw, 0, 3), bam(H, Pw, 3, 6))      # \"abc\" và \"abc\"\nprint(bam(H, Pw, 0, 3) == bam(H, Pw, 3, 6), bam(H, Pw, 1, 4) == bam(H, Pw, 4, 7), bam(H, Pw, 0, 2) == bam(H, Pw, 1, 3))",viz:[{type:"cells",of:"H",ptr:["i+1"],label:"H (băm tiền tố)"}],note:"H[i] là băm của tiền tố dài i. Đoạn s[0:3] và s[3:6] cùng là “abc” nên cùng số. Với Python, % luôn cho số không âm nên không cần cộng thêm M sau phép trừ."},cs:{code:"using System;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string s = \"abcabcab\";\n        ChuanBi(s);\n        Console.WriteLine(Bam(0, 3) + \" \" + Bam(3, 6));    // \"abc\" và \"abc\"\n        Console.WriteLine((Bam(0, 3) == Bam(3, 6)) + \" \" + (Bam(1, 4) == Bam(4, 7)) + \" \" + (Bam(0, 2) == Bam(1, 3)));\n    }\n}",viz:[{type:"cells",of:"H",ptr:["i+1"],label:"H (băm tiền tố)"}]}},{label:"Ví dụ: Rabin–Karp tìm mọi vị trí của mẫu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    string s = \"abracadabra\", p = \"abra\";\n    chuanBi(p);\n    long long hp = bam(0, p.size());     // băm của mẫu\n    chuanBi(s);\n    int m = p.size();\n    for (int i = 0; i + m <= (int)s.size(); i++) {\n        if (bam(i, i + m) == hp) cout << i << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+m-1"]},{type:"vars",names:["hp"]}],py:{code:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\ns, p = \"abracadabra\", \"abra\"\nHp, Pp = chuanBi(p)\nhp = bam(Hp, Pp, 0, len(p))       # băm của mẫu\nH, Pw = chuanBi(s)\nm = len(p)\nout = []\nfor i in range(len(s) - m + 1):\n    if bam(H, Pw, i, i + m) == hp:\n        out.append(i)\nprint(*out)",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+m-1"]},{type:"vars",names:["hp"]}]},cs:{code:"using System;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string s = \"abracadabra\", p = \"abra\";\n        ChuanBi(p);\n        long hp = Bam(0, p.Length);     // băm của mẫu (lấy trước khi chuẩn bị cho s)\n        ChuanBi(s);\n        int m = p.Length;\n        for (int i = 0; i + m <= s.Length; i++)\n        {\n            if (Bam(i, i + m) == hp) Console.Write(i + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+m-1"]},{type:"vars",names:["hp"]}]}},{label:"Ví dụ: Đếm đoạn con độ dài k khác nhau",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_set>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    string s = \"abababba\";\n    int k = 3;\n    chuanBi(s);\n    unordered_set<long long> da;\n    for (int i = 0; i + k <= (int)s.size(); i++) da.insert(bam(i, i + k));\n    cout << da.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+k-1"]},{type:"cont",of:"da"}],py:{code:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\ns = \"abababba\"\nk = 3\nH, Pw = chuanBi(s)\nda = set()\nfor i in range(len(s) - k + 1):\n    da.add(bam(H, Pw, i, i + k))\nprint(len(da))",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+k-1"]},{type:"cont",of:"da",as:"set"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string s = \"abababba\";\n        int k = 3;\n        ChuanBi(s);\n        HashSet<long> da = new HashSet<long>();\n        for (int i = 0; i + k <= s.Length; i++) da.Add(Bam(i, i + k));\n        Console.WriteLine(da.Count);\n    }\n}",viz:[{type:"cells",of:"s",ptr:["i"],range:["i","i+k-1"]},{type:"cont",of:"da",as:"set"}]}},{label:"Lỗi: hàm băm bằng tổng mã ký tự",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nlong long tongMa(const string& t) {\n    long long h = 0;\n    for (char c : t) h += c;      // không phân biệt thứ tự ký tự\n    return h;\n}\n\nint main() {\n    string a = \"listen\", b = \"silent\";\n    cout << (tongMa(a) == tongMa(b) ? \"bang nhau\" : \"khac nhau\") << \"\\n\";\n    return 0;\n}",py:{code:"def tongMa(t):\n    return sum(ord(c) for c in t)     # không phân biệt thứ tự ký tự\n\na, b = \"listen\", \"silent\"\nprint(\"bang nhau\" if tongMa(a) == tongMa(b) else \"khac nhau\")"},cs:{code:"using System;\n\nclass Program\n{\n    static long TongMa(string t)\n    {\n        long h = 0;\n        foreach (char c in t) h += c;      // không phân biệt thứ tự ký tự\n        return h;\n    }\n\n    static void Main()\n    {\n        string a = \"listen\", b = \"silent\";\n        Console.WriteLine(TongMa(a) == TongMa(b) ? \"bang nhau\" : \"khac nhau\");\n    }\n}"}}];
const sim34=makeSim2(document.getElementById("sim-l34"),{id:"s34",presets:PR34});
makeEx2(document.getElementById("ex-l34"),sim34,[{t:"Đếm số lần mẫu xuất hiện",d:"Đầu vào: dòng 1 là văn bản s, dòng 2 là mẫu p (chữ thường, 1 ≤ |p| ≤ |s| ≤ 10^5). Đầu ra: số vị trí i mà s[i..i+|p|) = p (các lần xuất hiện có thể chồng lên nhau).",tests:[{in:"abracadabra\nabra",out:"2"},{in:"aaaa\naa",out:"3"},{in:"abc\nd",out:"0"},{in:"x\nx",out:"1"},{in:"abababab\nabab",out:"3"},{in:"mississippi\nissi",out:"2"},{in:"\naaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",out:"201"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    string s, p;\n    cin >> s >> p;\n    int dem = 0;\n    // tính băm của p, rồi so với băm của mọi đoạn dài |p| của s\n    cout << dem << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"a".repeat(n)+"\n"+"a".repeat(Math.floor(n/2))+"b",ns:[500,2000,8000],need:"n",limit:n=>90*n+200,why:"So từng ký tự ở mỗi vị trí tốn O(n · m) khi s = “aaa…a”, p = “aa…ab”. Băm chuỗi so mỗi vị trí trong O(1)."},py:{start:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\ns = input()\np = input()\ndem = 0\n# tính băm của p, rồi so với băm của mọi đoạn dài len(p) của s\nprint(dem)",hints:["Tính hp = băm của p, và mảng băm tiền tố của s.","Với mỗi i từ 0 tới len(s) − len(p): so bam(i, i + len(p)) với hp, O(1) mỗi lần.","So s[i:i + m] == p tốn O(m) mỗi vị trí: O(n · m) khi văn bản và mẫu gần giống nhau."]},cs:{start:"using System;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string s = Console.ReadLine(), p = Console.ReadLine();\n        int dem = 0;\n        // tính băm của p, rồi so với băm của mọi đoạn dài p.Length của s\n        Console.WriteLine(dem);\n    }\n}",hints:["Tính hp = băm của p trước, vì ChuanBi(s) sẽ tạo lại mảng H.","Với mỗi i: so Bam(i, i + p.Length) với hp, O(1) mỗi lần.","So từng ký tự (hay s.Substring(i, m) == p) tốn O(m) mỗi vị trí: O(n · m)."]}},{t:"Số đoạn con độ dài k khác nhau",d:"Đầu vào: dòng 1 là n và k (1 ≤ k ≤ n ≤ 10^5), dòng 2 là chuỗi s dài n gồm chữ thường. Đầu ra: số đoạn con liên tiếp độ dài k khác nhau của s.",tests:[{in:"8 3\nabababba",out:"4"},{in:"4 2\naaaa",out:"1"},{in:"3 3\nabc",out:"1"},{in:"5 1\nabcde",out:"5"},{in:"9 3\nabcabcabc",out:"3"},{in:"1 1\nz",out:"1"}],start:"#include <iostream>\n#include <string>\n#include <unordered_set>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    int n, k;\n    string s;\n    cin >> n >> k >> s;\n    chuanBi(s);\n    unordered_set<long long> da;\n    // đưa băm của mọi đoạn dài k vào tập hợp\n    cout << da.size() << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+Math.floor(n/2)+"\n"+Array.from({length:n},(_,i)=>"ab"[(i*i+i>>1)%2]).join(""),ns:[500,2000,8000],need:"n",limit:n=>90*n+200,why:"Chép từng chuỗi con dài k vào tập hợp tốn O(n · k). Băm tiền tố cho mỗi đoạn một con số trong O(1)."},py:{start:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\nn, k = map(int, input().split())\ns = input()\nH, Pw = chuanBi(s)\nda = set()\n# đưa băm của mọi đoạn dài k vào tập hợp\nprint(len(da))",hints:["Mỗi đoạn s[i:i + k] được đại diện bằng một con số bam(H, Pw, i, i + k), tính O(1).","Đưa các số vào set rồi lấy len.","Đưa chính các chuỗi con s[i:i + k] vào set tốn O(k) mỗi đoạn để cắt và băm: O(n · k)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        string s = Console.ReadLine();\n        ChuanBi(s);\n        HashSet<long> da = new HashSet<long>();\n        // đưa băm của mọi đoạn dài k vào tập hợp\n        Console.WriteLine(da.Count);\n    }\n}",hints:["Mỗi đoạn s[i..i+k) được đại diện bằng một con số Bam(i, i + k), tính O(1).","Đưa các số vào HashSet<long> rồi lấy Count.","Đưa chính các chuỗi con (Substring) vào tập hợp tốn O(k) mỗi đoạn: O(n · k)."]}},{t:"So sánh nhiều cặp đoạn con",d:"Đầu vào: dòng 1 là chuỗi s (chữ thường, |s| ≤ 10^5); dòng 2 là q (≤ 10^5); q dòng sau mỗi dòng 4 số a b c d (1 ≤ a ≤ b ≤ |s|, 1 ≤ c ≤ d ≤ |s|, b − a = d − c). Đầu ra: với mỗi dòng, YES nếu đoạn s[a..b] bằng đoạn s[c..d] (đánh số từ 1, tính cả hai đầu), ngược lại NO.",tests:[{in:"abcabcabxabc\n6\n1 3 4 6\n1 3 7 9\n1 1 4 4\n1 12 1 12\n2 4 10 12\n1 2 2 3",out:"YES\nNO\nYES\nYES\nNO\nNO"},{in:"\n30\n1 50 3 52\n8 57 10 59\n15 64 17 66\n22 71 24 73\n29 78 31 80\n36 85 38 87\n43 92 45 94\n50 99 52 101\n57 106 59 108\n64 113 66 115\n71 120 73 122\n78 127 80 129\n85 134 87 136\n92 141 94 143\n99 148 101 150\n106 155 108 157\n113 162 115 164\n120 169 122 171\n127 176 129 178\n134 183 136 185\n141 190 143 192\n148 197 150 199\n155 204 157 206\n162 211 164 213\n169 218 171 220\n176 225 178 227\n183 232 185 234\n190 239 192 241\n197 246 199 248\n1 100 2 101",out:"YES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nYES\nNO"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst long long B = 131, M = 1000000007;\nlong long H[100001], P[100001];\n\nvoid chuanBi(const string& s) {\n    P[0] = 1;\n    for (int i = 0; i < (int)s.size(); i++) {\n        H[i + 1] = (H[i] * B + s[i]) % M;\n        P[i + 1] = P[i] * B % M;\n    }\n}\n\nlong long bam(int l, int r) {          // băm của đoạn s[l..r), O(1)\n    return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n}\n\nint main() {\n    string s;\n    int q;\n    cin >> s >> q;\n    chuanBi(s);\n    for (int i = 0; i < q; i++) {\n        int a, b, c, d;\n        cin >> a >> b >> c >> d;\n        // đổi sang đoạn [a - 1, b) và [c - 1, d) rồi so băm\n    }\n    return 0;\n}",perf:{gen:n=>"a".repeat(n)+"\n"+n+"\n"+Array.from({length:n},(_,i)=>"1 "+Math.floor(n/2)+" "+(Math.floor(n/2)+1)+" "+n).join("\n"),ns:[500,2000,8000],need:"n",limit:n=>120*n+200,why:"So từng ký tự của hai đoạn dài tốn O(n) mỗi câu hỏi, tổng O(n · q). Băm tiền tố trả lời mỗi câu trong O(1)."},py:{start:"B, M = 131, 1000000007\n\ndef chuanBi(s):\n    \"\"\"trả về (H, P): H[i] băm tiền tố dài i, P[i] = B^i mod M\"\"\"\n    H = [0] * (len(s) + 1)\n    P = [1] * (len(s) + 1)\n    for i, c in enumerate(s):\n        H[i + 1] = (H[i] * B + ord(c)) % M\n        P[i + 1] = P[i] * B % M\n    return H, P\n\ndef bam(H, P, l, r):          # băm của đoạn s[l:r], O(1)\n    return (H[r] - H[l] * P[r - l]) % M\n\ns = input()\nq = int(input())\nH, Pw = chuanBi(s)\nout = []\nfor _ in range(q):\n    a, b, c, d = map(int, input().split())\n    # đổi sang đoạn s[a - 1:b] và s[c - 1:d] rồi so băm\nprint(\"\\n\".join(out))",hints:["Đoạn s[a..b] (đánh số từ 1, tính cả hai đầu) chính là s[a − 1:b] của Python.","Mỗi câu hỏi chỉ so hai con số: O(1).","So s[a − 1:b] == s[c − 1:d] tốn O(độ dài) mỗi câu hỏi."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    const long B = 131, M = 1000000007;\n    static long[] H, P;\n\n    static void ChuanBi(string s)\n    {\n        H = new long[s.Length + 1];\n        P = new long[s.Length + 1];\n        P[0] = 1;\n        for (int i = 0; i < s.Length; i++)\n        {\n            H[i + 1] = (H[i] * B + s[i]) % M;\n            P[i + 1] = P[i] * B % M;\n        }\n    }\n\n    static long Bam(int l, int r)          // băm của đoạn s[l..r), O(1)\n    {\n        return ((H[r] - H[l] * P[r - l]) % M + M) % M;\n    }\n\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        int q = int.Parse(Console.ReadLine());\n        ChuanBi(s);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < q; i++)\n        {\n            int[] x = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            // đoạn [x[0] - 1, x[1]) và [x[2] - 1, x[3]): so băm\n        }\n        Console.Write(sb);\n    }\n}",hints:["Đoạn s[a..b] (đánh số từ 1, tính cả hai đầu) chính là đoạn [a − 1, b) theo chỉ số từ 0.","Mỗi câu hỏi chỉ so hai con số: O(1).","So từng ký tự tốn O(độ dài) mỗi câu hỏi: tổng O(n · q)."]}}]);

makeQuiz("quiz34","score34",[{"q": "H là băm tiền tố, P là lũy thừa của B. Băm của đoạn s[l..r) là?", "o": ["H[r] − H[l]", "H[r] − H[l]·P[r − l]", "H[r]·P[l]", "(H[r] + H[l]) / 2"], "a": 1, "e": "Phải “dịch” H[l] sang trái r − l vị trí trước khi trừ."}, {"q": "Hai đoạn con có băm khác nhau thì?", "o": ["Có thể giống nhau", "Chắc chắn khác nhau", "Chắc chắn giống nhau", "Không kết luận được gì"], "a": 1, "e": "Cùng chuỗi luôn cùng băm; khác băm thì chắc chắn khác chuỗi. Chiều ngược lại mới có thể sai (va chạm)."}, {"q": "Vì sao không dùng tổng mã các ký tự làm hàm băm?", "o": ["Vì chậm", "Vì đổi chỗ các ký tự không làm đổi tổng", "Vì tràn số", "Vì không lấy dư được"], "a": 1, "e": "“ab” và “ba” cùng tổng."}, {"q": "Rabin–Karp tìm mẫu dài m trong văn bản dài n tốn?", "o": ["O(n · m)", "O(n + m)", "O(n log m)", "O(m²)"], "a": 1, "e": "Chuẩn bị O(n + m), mỗi vị trí so một con số O(1)."}]);

